sailor=next(v for v in state.values() if v['kind']=='assertion' and v.get('value')=='sjómaður');lines.append(f'- Bjarni sem sjómaður er óstaðfest skráning ({label(sailor)}).')
lines+=['','Fimm opnar spurningar, án svara:']
for v in summary['open_questions']:lines.append('- '+v['text']+f' ({label(v)}).')
lines+=['',f'Yfirlitið er afleitt af heimildafærslunum. Fyrri vistunarpunktur: {ctx["checkpoint"]["git_head"]}, röð {ctx["checkpoint"]["sequence"]}. Núverandi færsla: {x["exchange_id"]}, röð {x["sequence"]}; lota {label(session2)}; yfirferðarstilling {label(project)}.','Ég staldra við án frekari þróunar.']
